import functools

def semver_sort(versions):
    def parse(v):
        core = v.split('+', 1)[0]
        if '-' in core:
            main, pre = core.split('-', 1)
        else:
            main, pre = core, None
        major, minor, patch = (int(x) for x in main.split('.'))
        pre_ids = pre.split('.') if pre is not None else None
        return (major, minor, patch, pre_ids)

    def cmp_pre(a, b):
        # a, b are lists of pre-release identifiers or None
        if a is None and b is None:
            return 0
        if a is None:
            return 1
        if b is None:
            return -1
        for i in range(min(len(a), len(b))):
            ai, bi = a[i], b[i]
            ai_num = ai.isdigit()
            bi_num = bi.isdigit()
            if ai_num and bi_num:
                na, nb = int(ai), int(bi)
                if na != nb:
                    return -1 if na < nb else 1
            elif ai_num and not bi_num:
                return -1
            elif not ai_num and bi_num:
                return 1
            else:
                if ai != bi:
                    return -1 if ai < bi else 1
        if len(a) != len(b):
            return -1 if len(a) < len(b) else 1
        return 0

    def cmp(v1, v2):
        p1 = parse(v1)
        p2 = parse(v2)
        for i in range(3):
            if p1[i] != p2[i]:
                return -1 if p1[i] < p2[i] else 1
        return cmp_pre(p1[3], p2[3])

    indexed = list(enumerate(versions))
    indexed.sort(key=functools.cmp_to_key(lambda x, y: cmp(x[1], y[1]) or (x[0] - y[0])))
    return [v for _, v in indexed]

